-- ============================================================================
-- WDOS Migration 140 — WODDI HQ Messaging Engine (Phase 186)
-- Built to the Founder's "WDOS – WODDI HQ Personalised Messaging & Weekly
-- Inspiration Framework" and the "WDOS Five Year Monday Weekly Inspirational
-- Messages Master".
--   • hq_messages        one record per message ID per network, with status,
--                        approval, scheduling, audience, language and version
--   • hq_message_inserts the exact role-specific ACT line per leadership level
--   • hq_message_delivery one publication history per recipient + message +
--                        version (duplicate prevention, open/read tracking)
--   • my_hq_message()    resolves the Monday message for the signed-in leader,
--                        personalises it, records the delivery and returns the
--                        card exactly as the framework specifies
--   • hq_message_stats() HQ analytics: targeted / displayed / opened / read
-- Seeded with the first 13 weeks (three months) for WGMN and WNNN.
-- The old title-only weekly inspiration content is removed, as instructed.
-- ============================================================================

create table if not exists public.hq_messages (
  id            uuid primary key default gen_random_uuid(),
  message_id    text not null,                       -- WODDI-WI-001
  category      text not null default 'weekly_inspiration',
  network       text not null check (network in ('WGMN','WNNN')),
  language      text not null default 'en',
  version       int  not null default 1,
  year_no       int  not null,
  quarter_no    int,
  week_no       int,                                 -- 1..52 within the year
  theme         text,
  headline      text not null,
  graphic_key_thought text,
  greeting      text not null default 'Dear {{FirstName}},',
  body          text not null,
  key_thought   text,
  closing       text not null default 'Thank you for leading with purpose and care.',
  signature     text not null default 'WODDI HQ',
  tagline       text,
  graphic_slug  text,                                -- /assets/hq-messages/<slug>.svg
  graphic_direction text,
  audience_roles text[],                             -- null = every leadership level
  audience_countries text[],                         -- null = all countries
  status        text not null default 'approved'
                check (status in ('draft','review','returned','approved','scheduled','published','expired','archived')),
  approved_by   uuid references public.profiles(id),
  approved_at   timestamptz,
  publish_from  date,                                -- the Monday it is released
  publish_until date,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (message_id, network, language, version)
);
create index if not exists hq_messages_week_idx on public.hq_messages (network, year_no, week_no);

create table if not exists public.hq_message_inserts (
  id         uuid primary key default gen_random_uuid(),
  message_id text not null,
  network    text not null check (network in ('WGMN','WNNN')),
  role       text not null,
  insert_text text not null,
  unique (message_id, network, role)
);

create table if not exists public.hq_message_delivery (
  id           uuid primary key default gen_random_uuid(),
  profile_id   uuid not null references public.profiles(id) on delete cascade,
  message_id   text not null,
  network      text not null,
  version      int  not null default 1,
  channel      text not null default 'dashboard',
  displayed_at timestamptz not null default now(),
  opened_at    timestamptz,
  read_at      timestamptz,
  unique (profile_id, message_id, version, channel)
);
create index if not exists hq_delivery_msg_idx on public.hq_message_delivery (message_id);

alter table public.hq_messages        enable row level security;
alter table public.hq_message_inserts enable row level security;
alter table public.hq_message_delivery enable row level security;
drop policy if exists hq_messages_read on public.hq_messages;
create policy hq_messages_read on public.hq_messages for select to authenticated using (true);
drop policy if exists hq_inserts_read on public.hq_message_inserts;
create policy hq_inserts_read on public.hq_message_inserts for select to authenticated using (true);
drop policy if exists hq_messages_manage on public.hq_messages;
create policy hq_messages_manage on public.hq_messages for all to authenticated
  using (public.is_case_hq()) with check (public.is_case_hq());
drop policy if exists hq_inserts_manage on public.hq_message_inserts;
create policy hq_inserts_manage on public.hq_message_inserts for all to authenticated
  using (public.is_case_hq()) with check (public.is_case_hq());
drop policy if exists hq_delivery_own on public.hq_message_delivery;
create policy hq_delivery_own on public.hq_message_delivery for select to authenticated
  using (profile_id = auth.uid() or public.is_case_hq());

-- The old title-only weekly inspiration content is replaced by this engine.
delete from public.engagement_content where kind = 'weekly';

insert into public.hq_messages
 (message_id, network, year_no, quarter_no, week_no, theme, headline, graphic_key_thought,
  body, key_thought, closing, tagline, graphic_slug, graphic_direction, status, publish_from, publish_until)
 values ('WODDI-WI-001', 'WGMN', 1, 1, 1, 'Identity and Purpose',
  'You Are Part of Something Bigger Than Yourself', 'Rooted women lead with purpose and strengthen others through their example.', 'As {{RoleTitle}} in {{LocationName}}, your WGMN leadership is laying a foundation of identity, purpose and dependable service. Your leadership reaches women, families and communities through the choices you make each day. This week''s focus, ''You Are Part of Something Bigger Than Yourself'', invites you to turn experience into an example others can trust. Apply it with wisdom, dignity and steady follow-through. When one woman leads responsibly, she makes it easier for other women to grow, contribute and strengthen the people around them.', 'Rooted women lead with purpose and strengthen others through their example.',
  'Thank you for leading WGMN with purpose and care.', 'WGMN — Nurturing women, strengthening families.', 'wi001-wgmn', 'Authentic African woman aged 30 or above volunteer leader in purposeful action; professional natural light; WODDI colour accents; uncluttered composition. Build as a polished WODDI/WGMN graphic. Overlay only the approved headline and key thought; keep the full personalised message outside the artwork.', 'approved', null, null)
 on conflict (message_id, network, language, version) do update
   set headline = excluded.headline, body = excluded.body, key_thought = excluded.key_thought,
       graphic_key_thought = excluded.graphic_key_thought, theme = excluded.theme,
       graphic_slug = excluded.graphic_slug, tagline = excluded.tagline;
insert into public.hq_messages
 (message_id, network, year_no, quarter_no, week_no, theme, headline, graphic_key_thought,
  body, key_thought, closing, tagline, graphic_slug, graphic_direction, status, publish_from, publish_until)
 values ('WODDI-WI-001', 'WNNN', 1, 1, 1, 'Identity and Purpose',
  'You Are the Next Generation of Women Leaders', 'You are not waiting to become a leader; you are learning to lead responsibly now.', 'As {{RoleTitle}} in {{LocationName}}, your WNNN leadership is strengthening young women in identity, voice and values. You do not need to wait for a future title or a perfect moment to lead well. This week''s focus, ''You Are the Next Generation of Women Leaders'', can shape the choices you make now in your studies, work, service and relationships. Take one responsible step, learn from it and keep growing. Your example can help another young woman believe that her voice, values and contribution matter.', 'You are not waiting to become a leader; you are learning to lead responsibly now.',
  'Thank you for leading WNNN with purpose and care.', 'WNNN — Raising the next generation of women leaders.', 'wi001-wnnn', 'Authentic young African women aged 18 to 29 in a safe, confident and purposeful leadership setting; contemporary but professional; inclusive; WODDI colour accents. Build as a polished WODDI/WNNN graphic. Overlay only the approved headline and key thought; keep the full personalised message outside the artwork.', 'approved', null, null)
 on conflict (message_id, network, language, version) do update
   set headline = excluded.headline, body = excluded.body, key_thought = excluded.key_thought,
       graphic_key_thought = excluded.graphic_key_thought, theme = excluded.theme,
       graphic_slug = excluded.graphic_slug, tagline = excluded.tagline;
