 values ('WODDI-WI-006', 'WGMN', 1, 1, 6, 'Identity and Purpose',
  'Your Role Is a Trust', 'A dependable local action can strengthen the wider African network.', 'As {{RoleTitle}} in {{LocationName}}, your WGMN leadership is laying a foundation of identity, purpose and dependable service. Leadership within WGMN should leave women stronger, families better supported and communities more connected. This week''s theme, ''Your Role Is a Trust'', gives you a practical opportunity to strengthen that influence. Act within your authority, involve the right people and record the result so that good work can be recognised, supported and repeated.', 'A dependable local action can strengthen the wider African network.',
  'Thank you for leading WGMN with purpose and care.', 'WGMN — Nurturing women, strengthening families.', 'wi006-wgmn', 'Authentic African woman aged 30 or above volunteer leader in purposeful action; professional natural light; WODDI colour accents; uncluttered composition. Build as a polished WODDI/WGMN graphic. Overlay only the approved headline and key thought; keep the full personalised message outside the artwork.', 'approved', null, null)
 on conflict (message_id, network, language, version) do update
   set headline = excluded.headline, body = excluded.body, key_thought = excluded.key_thought,
       graphic_key_thought = excluded.graphic_key_thought, theme = excluded.theme,
       graphic_slug = excluded.graphic_slug, tagline = excluded.tagline;
