  body, key_thought, closing, tagline, graphic_slug, graphic_direction, status, publish_from, publish_until)
 values ('WODDI-WI-011', 'WGMN', 1, 1, 11, 'Identity and Purpose',
  'Your Presence Can Create Hope', 'Experience becomes valuable when it is used to lift another woman.', 'As {{RoleTitle}} in {{LocationName}}, your WGMN leadership is laying a foundation of identity, purpose and dependable service. The Good Mother spirit is expressed through purposeful influence, not through title alone. The message ''Your Presence Can Create Hope'' should be visible in how you communicate, mentor, organise and follow through. Your example can help another woman become more rooted in identity, more confident in purpose and more intentional about her family and community.', 'Experience becomes valuable when it is used to lift another woman.',
  'Thank you for leading WGMN with purpose and care.', 'WGMN — Nurturing women, strengthening families.', 'wi011-wgmn', 'Confident African woman aged 30 or above leader moving forward in a bright, open setting; subtle sense of direction, possibility and purpose. Build as a polished WODDI/WGMN graphic. Overlay only the approved headline and key thought; keep the full personalised message outside the artwork.', 'approved', null, null)
 on conflict (message_id, network, language, version) do update
   set headline = excluded.headline, body = excluded.body, key_thought = excluded.key_thought,
       graphic_key_thought = excluded.graphic_key_thought, theme = excluded.theme,
       graphic_slug = excluded.graphic_slug, tagline = excluded.tagline;
