  body, key_thought, closing, tagline, graphic_slug, graphic_direction, status, publish_from, publish_until)
 values ('WODDI-WI-012', 'WGMN', 1, 1, 12, 'Identity and Purpose',
  'Confidence Grows Through Responsible Action', 'Healthy service protects both the mission and the woman who serves.', 'As {{RoleTitle}} in {{LocationName}}, your WGMN leadership is laying a foundation of identity, purpose and dependable service. Women often carry several responsibilities at the same time, so intentional leadership matters. Let ''Confidence Grows Through Responsible Action'' help you identify what deserves attention now, what can be delegated and what must be followed through. A clear and measured action can protect your wellbeing while still strengthening the women and leaders who depend on your guidance.', 'Healthy service protects both the mission and the woman who serves.',
  'Thank you for leading WGMN with purpose and care.', 'WGMN — Nurturing women, strengthening families.', 'wi012-wgmn', 'Authentic African woman aged 30 or above volunteer leader in purposeful action; professional natural light; WODDI colour accents; uncluttered composition. Build as a polished WODDI/WGMN graphic. Overlay only the approved headline and key thought; keep the full personalised message outside the artwork.', 'approved', null, null)
 on conflict (message_id, network, language, version) do update
   set headline = excluded.headline, body = excluded.body, key_thought = excluded.key_thought,
       graphic_key_thought = excluded.graphic_key_thought, theme = excluded.theme,
       graphic_slug = excluded.graphic_slug, tagline = excluded.tagline;
insert into public.hq_messages
 (message_id, network, year_no, quarter_no, week_no, theme, headline, graphic_key_thought,
  body, key_thought, closing, tagline, graphic_slug, graphic_direction, status, publish_from, publish_until)
 values ('WODDI-WI-012', 'WNNN', 1, 1, 12, 'Identity and Purpose',
  'You Are Becoming', 'You can ask for guidance and still be a strong young leader.', 'As {{RoleTitle}} in {{LocationName}}, your WNNN leadership is strengthening young women in identity, voice and values. Young leadership grows through practice. Let ''You Are Becoming'' guide one real decision this week. You may be balancing education, work, family responsibilities and service, so choose a step that is clear and realistic. Completing one meaningful action with integrity is stronger than making many promises you cannot sustain. You do not need to know everything; remain teachable, act responsibly and keep moving forward.', 'You can ask for guidance and still be a strong young leader.',
  'Thank you for leading WNNN with purpose and care.', 'WNNN — Raising the next generation of women leaders.', 'wi012-wnnn', 'Authentic young African women aged 18 to 29 in a safe, confident and purposeful leadership setting; contemporary but professional; inclusive; WODDI colour accents. Build as a polished WODDI/WNNN graphic. Overlay only the approved headline and key thought; keep the full personalised message outside the artwork.', 'approved', null, null)
