-- The leader-facing title for a role, in her network's language (WGMN uses
-- Representative/Coordinator, WNNN uses Lead).
create or replace function public.role_title(p_role text, p_net text)
returns text language sql immutable as $$
  select case p_role
    when 'country_rep' then case when p_net = 'WNNN' then 'Country Lead' else 'Country Representative' end
    when 'deputy_country_rep' then case when p_net = 'WNNN' then 'Deputy Country Lead' else 'Deputy Country Representative' end
    when 'state_coordinator' then case when p_net = 'WNNN' then 'State or Regional Lead' else 'State or Regional Coordinator' end
    when 'assistant_state_coordinator' then case when p_net = 'WNNN' then 'Assistant State or Regional Lead' else 'Assistant State or Regional Coordinator' end
    when 'district_coordinator' then case when p_net = 'WNNN' then 'LGA, District or Municipality Lead' else 'LGA, District or Municipality Coordinator' end
    when 'assistant_district_coordinator' then case when p_net = 'WNNN' then 'Assistant LGA, District or Municipality Lead' else 'Assistant LGA, District or Municipality Coordinator' end
    when 'cluster_coordinator' then case when p_net = 'WNNN' then 'Community Cluster or Ward Lead' else 'Community Cluster or Ward Coordinator' end
    when 'assistant_cluster_coordinator' then case when p_net = 'WNNN' then 'Assistant Community Cluster or Ward Lead' else 'Assistant Community Cluster or Ward Coordinator' end
    when 'chapter_lead' then case when p_net = 'WNNN' then 'Chapter Lead' else 'Chapter Coordinator' end
    when 'assistant_chapter_lead' then case when p_net = 'WNNN' then 'Assistant Chapter Lead' else 'Assistant Chapter Coordinator' end
    else null end;
$$;

-- Note: role_assignments.role is the role_code ENUM, not text, so every call
-- site casts it (ra.role::text). hq_message_inserts.role is plain text.

-- ---------------------------------------------------------------------------
-- The Monday message for the signed-in leader.
-- Released on Monday, stays available for that week, then moves to the archive.
-- Personalises {{FirstName}}, {{RoleTitle}}, {{LocationName}} and inserts the
-- one role-specific ACT line matching her exact leadership level.
-- ---------------------------------------------------------------------------
create or replace function public.my_hq_message(p_record boolean default true)
returns jsonb language plpgsql
security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  p profiles%rowtype;
  seat record;
  net text; role_code text; role_title text; loc text;
  wk int; yr int := 1; monday date;
  m hq_messages%rowtype; ins text; out_body text;
begin
  if me is null then return null; end if;
  select * into p from profiles where id = me;
  if not found then return null; end if;

  select ra.role::text as role, ou.name as unit_name, ou.level into seat
    from role_assignments ra join org_units ou on ou.id = ra.org_unit_id
   where ra.profile_id = me and ra.ends_at is null
   order by case ra.role when 'country_rep' then 1 when 'deputy_country_rep' then 2 else 3 end
   limit 1;

  net := coalesce(p.network::text, 'WGMN');
  role_code := coalesce(seat.role, '');
  role_title := coalesce(public.role_title(role_code, net), p.role_applied, 'volunteer leader');
  loc := coalesce(seat.unit_name, p.state_region, p.country, 'your area');

  -- Monday of the recipient's current week, and the week number in the cycle
  monday := (current_date - ((extract(isodow from current_date)::int - 1)))::date;
  wk := least(13, greatest(1, ((monday - date '2026-09-14') / 7)::int + 1));
  if monday < date '2026-09-14' then wk := 1; end if;

  select * into m from hq_messages
   where network = net and week_no = wk and year_no = yr
     and status in ('approved','scheduled','published')
     and (audience_roles is null or role_code = any(audience_roles))
     and (audience_countries is null or coalesce(p.country,'') = any(audience_countries))
   order by version desc limit 1;
  if not found then return null; end if;

  select insert_text into ins from hq_message_inserts
   where message_id = m.message_id and network = net and role = role_code;

  out_body := replace(replace(replace(m.body,
      '{{FirstName}}', p.first_name),
      '{{RoleTitle}}', role_title),
      '{{LocationName}}', loc);

  if p_record then
    insert into hq_message_delivery (profile_id, message_id, network, version)
    values (me, m.message_id, net, m.version)
    on conflict (profile_id, message_id, version, channel) do nothing;
  end if;

  return jsonb_build_object(
    'message_id', m.message_id, 'category', m.category, 'network', net,
    'week_no', m.week_no, 'theme', m.theme, 'week_of', to_char(monday, 'DD FMMonth YYYY'),
    'greeting', replace(m.greeting, '{{FirstName}}', p.first_name),
    'first_name', p.first_name, 'role_title', role_title, 'location', loc,
    'headline', m.headline, 'body', out_body, 'key_thought', m.key_thought,
    'act', ins, 'closing', m.closing, 'signature', m.signature, 'tagline', m.tagline,
    'graphic', '/assets/hq-messages/' || m.graphic_slug || '.svg',
    'graphic_headline', m.headline, 'graphic_key_thought', m.graphic_key_thought,
    'released_on', monday);
end; $$;
revoke execute on function public.my_hq_message(boolean) from anon;

-- Mark opened / read (analytics definitions: displayed on render, opened when
-- the leader expands it, read when she reaches the end of the message).
create or replace function public.hq_message_seen(p_message_id text, p_state text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return; end if;
  update hq_message_delivery
     set opened_at = case when p_state in ('opened','read') then coalesce(opened_at, now()) else opened_at end,
         read_at   = case when p_state = 'read' then coalesce(read_at, now()) else read_at end
   where profile_id = auth.uid() and message_id = p_message_id;
end; $$;
revoke execute on function public.hq_message_seen(text, text) from anon;

-- Her archive: every HQ message already delivered to her.
create or replace function public.my_hq_message_archive(p_limit int default 30)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(x order by x->>'displayed_at' desc), '[]'::jsonb) from (
    select jsonb_build_object(
      'message_id', d.message_id, 'network', d.network, 'week_no', m.week_no,
      'headline', m.headline, 'theme', m.theme, 'key_thought', m.key_thought,
      'body', replace(replace(replace(m.body, '{{FirstName}}', p.first_name),
                '{{RoleTitle}}', coalesce(public.role_title((select ra.role::text from role_assignments ra
                    where ra.profile_id = p.id and ra.ends_at is null limit 1), d.network), 'volunteer leader')),
                '{{LocationName}}', coalesce(p.state_region, p.country, 'your area')),
      'graphic', '/assets/hq-messages/' || m.graphic_slug || '.svg',
      'displayed_at', d.displayed_at, 'read_at', d.read_at) as x
      from hq_message_delivery d
      join hq_messages m on m.message_id = d.message_id and m.network = d.network and m.version = d.version
      join profiles p on p.id = d.profile_id
     where d.profile_id = auth.uid()
     order by d.displayed_at desc
     limit greatest(1, least(100, p_limit))) s;
$$;
revoke execute on function public.my_hq_message_archive(int) from anon;

-- HQ analytics for one message (targeted / displayed / opened / read).
create or replace function public.hq_message_stats(p_message_id text default null)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'message_id', s.message_id, 'network', s.network, 'week_no', s.week_no,
      'headline', s.headline, 'targeted', s.targeted, 'displayed', s.displayed,
      'opened', s.opened, 'read', s.read_n,
      'open_rate', case when s.displayed > 0 then round(100.0 * s.opened / s.displayed, 1) else 0 end)
      order by s.week_no, s.network), '[]'::jsonb)
  from (
    select m.message_id, m.network, m.week_no, m.headline,
           (select count(*) from profiles pr where pr.is_leader and coalesce(pr.network::text, 'WGMN') = m.network) as targeted,
           count(d.id) as displayed,
           count(d.opened_at) as opened,
           count(d.read_at) as read_n
      from hq_messages m
      left join hq_message_delivery d on d.message_id = m.message_id and d.network = m.network
     where p_message_id is null or m.message_id = p_message_id
     group by m.message_id, m.network, m.week_no, m.headline) s;
$$;
revoke execute on function public.hq_message_stats(text) from anon;

insert into public.schema_migrations (version, name)
values (140, 'hq_messaging_engine') on conflict (version) do nothing;
